#include <vector>
#include <string>
#include <unordered_set>

class Solution {
public:
    std::string destCity(std::vector<std::vector<std::string>>& paths) {
        std::unordered_set<std::string> starts;
        for (const auto& p : paths) starts.insert(p[0]);
        for (const auto& p : paths) {
            if (!starts.count(p[1])) return p[1];
        }
        return "";
    }
};

import java.util.*;

class Solution {
    public String destCity(List<List<String>> paths) {
        Set<String> starts = new HashSet<>();
        for (List<String> p : paths) starts.add(p.get(0));
        for (List<String> p : paths) {
            if (!starts.contains(p.get(1))) return p.get(1);
        }
        return "";
    }
}

var destCity = function(paths) {
    const starts = new Set(paths.map(p => p[0]));
    for (const p of paths) {
        if (!starts.has(p[1])) return p[1];
    }
    return "";
};
